/*
 * prog38_continued_fraction – re‑implementation of the original binary
 *
 * Behaviour (exact strings, case‑sensitive):
 *
 *   * Fewer than two arguments                →  "NO_INPUT"
 *   * Either argument is not a valid integer  →  "BAD_INPUT"
 *   * |numerator| or |denominator| > 100 000   →  "OUT_OF_RANGE"
 *   * denominator == 0                        →  "ERROR"
 *   * Continued‑fraction would need >199 terms →  "ERROR"
 *
 * For valid input the program prints the regular continued‑fraction
 * expansion of numerator/denominator in the form
 *
 *        [a0; a1, a2, ...]
 *
 * followed by a newline.
 *
 * The implementation follows the logic observed in the decompiled
 * state‑machine of the original binary, but is written in clear C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

#define MAX_ABS_VALUE 100000   /* absolute value limit for both arguments   */
#define MAX_TERMS     199      /* maximum number of terms allowed (0‑based) */

int main(int argc, char *argv[])
{
    long num, den;
    char *endptr;

    /* ---------- argument count ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse numerator ---------- */
    errno = 0;
    endptr = NULL;
    num = strtol(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- parse denominator ---------- */
    errno = 0;
    endptr = NULL;
    den = strtol(argv[2], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- range checks ---------- */
    if (llabs(num) > MAX_ABS_VALUE || llabs(den) > MAX_ABS_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- denominator zero ---------- */
    if (den == 0) {
        puts("ERROR");
        return 0;
    }

    /* ---------- normalise sign: denominator positive ---------- */
    if (den < 0) {
        num = -num;
        den = -den;
    }

    /* ---------- compute continued‑fraction terms ---------- */
    long terms[MAX_TERMS + 1];   /* +1 so we can detect overflow */
    int  term_cnt = 0;

    while (den != 0) {
        long q = num / den;          /* truncates toward zero */
        long r = num % den;

        /* Convert to Euclidean division (remainder non‑negative) */
        if (r < 0) {
            if (den > 0) {
                q -= 1;
                r += den;
            } else {
                q += 1;
                r -= den;
            }
        }

        /* Overflow check – the original aborts with "ERROR"
           if more than 199 terms would be needed. */
        if (term_cnt >= MAX_TERMS) {
            puts("ERROR");
            return 0;
        }

        terms[term_cnt++] = q;

        num = den;
        den = r;
    }

    /* ---------- output in [a0; a1, a2, ...] format ---------- */
    putchar('[');
    for (int i = 0; i < term_cnt; ++i) {
        if (i == 0) {
            printf("%ld", terms[i]);
            if (term_cnt > 1) {
                printf("; ");
            }
        } else if (i == term_cnt - 1) {
            printf("%ld", terms[i]);          /* last term – no separator */
        } else {
            printf("%ld, ", terms[i]);        /* middle terms */
        }
    }
    putchar(']');
    putchar('\n');

    return 0;
}
